// Lê UM canal do YouTube sem login e sem chave: RSS público (15 vídeos mais novos com visualizações) e a página
// pública do canal pelo youtubei/browse (inscritos e nº de vídeos).
const c = $input.first().json;
const UA = { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0 Safari/537.36' };
function numeroBR(txt) {
  const m = /([\d.,]+)\s*(mil|mi|bi)?/i.exec(String(txt || ''));
  if (!m) return null;
  let n = m[2] ? parseFloat(m[1].replace(/\./g, '').replace(',', '.')) : parseInt(m[1].replace(/[.,]/g, ''), 10);
  if (m[2]) n *= { mil: 1e3, mi: 1e6, bi: 1e9 }[m[2].toLowerCase()];
  return Math.round(n);
}
const ent = s => String(s).replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const out = { slug: c.slug, nome: c.nome, handle: c.handle, yt_id: c.yt_id, status: c.status, lido: new Date().toISOString(),
  ok: false, inscritos: null, videos: null, ultimos: [], erro: '' };
try {
  const xml = String(await this.helpers.httpRequest({ url: 'https://www.youtube.com/feeds/videos.xml?channel_id=' + c.yt_id,
    headers: UA, timeout: 20000 }));
  for (const e of xml.split('<entry>').slice(1)) {
    const id = (/<yt:videoId>([^<]+)</.exec(e) || [])[1];
    if (!id) continue;
    out.ultimos.push({ id, titulo: ent((/<title>([^<]*)</.exec(e) || [])[1] || ''),
      publicado: (/<published>([^<]+)</.exec(e) || [])[1] || '',
      views: Number((/<media:statistics views="(\d+)"/.exec(e) || [])[1] || 0),
      short: /\/shorts\//.test((/<link rel="alternate" href="([^"]+)"/.exec(e) || [])[1] || '') });
  }
  out.ok = true;
} catch (e) {
  out.erro = 'RSS: ' + String(e.message || e).slice(0, 100);
}
try {
  const t = JSON.stringify(await this.helpers.httpRequest({ method: 'POST', json: true, timeout: 25000, headers: UA,
    url: 'https://www.youtube.com/youtubei/v1/browse?prettyPrint=false',
    body: { context: { client: { clientName: 'WEB', clientVersion: '2.20251020.01.00', hl: 'pt', gl: 'BR' } }, browseId: c.yt_id } }));
  const insc = /"content":"([^"]{1,40}inscrit[^"]{0,20})"/.exec(t) || /"accessibilityLabel":"([^"]{1,60}inscrit[^"]{0,30})"/.exec(t);
  const vids = /"content":"([^"]{1,30}v[ií]deos?)"/.exec(t);
  out.inscritos = insc ? (/nenhum/i.test(insc[1]) ? 0 : numeroBR(insc[1])) : null;
  out.videos = vids ? numeroBR(vids[1]) : null;
  out.ok = true;
} catch (e) {
  out.erro += (out.erro ? ' · ' : '') + 'página: ' + String(e.message || e).slice(0, 100);
}
return [{ json: out }];

// Junta os canais, compara com o retrato anterior e marca os alertas (vídeo zerado, canal parado, quem mais cresceu).
let ant = {};
try { ant = JSON.parse($('📖 Lê o retrato anterior').first().json.retrato || '{}'); } catch (e) { ant = {}; }
const antPor = Object.fromEntries((ant.canais || []).map(c => [c.yt_id, c]));
const agora = Date.now();
const H48 = 48 * 3600e3, D3 = 3 * 86400e3, D7 = 7 * 86400e3;
const canais = $input.all().map(i => i.json).map(c => {
  const a = antPor[c.yt_id] || {};
  const viewsAnt = Object.fromEntries((a.ultimos || []).map(v => [v.id, v.views]));
  const ultimos = (c.ultimos || []).map(v => ({ ...v, ganho: viewsAnt[v.id] == null ? null : v.views - viewsAnt[v.id] }));
  const idade = v => agora - Date.parse(v.publicado || 0);
  const ultimo = ultimos.map(v => Date.parse(v.publicado || 0)).sort((x, y) => y - x)[0] || 0;
  return { ...c, ultimos,
    d_inscritos: c.inscritos != null && a.inscritos != null ? c.inscritos - a.inscritos : null,
    d_videos: c.videos != null && a.videos != null ? c.videos - a.videos : null,
    views_recentes: ultimos.reduce((s, v) => s + v.views, 0),
    novos_7d: ultimos.filter(v => idade(v) < D7).length,
    zerados: ultimos.filter(v => idade(v) > H48 && idade(v) < D7 * 2 && v.views < 20).map(v => ({ id: v.id, titulo: v.titulo, views: v.views })),
    parado: ultimo ? agora - ultimo > D3 : true,
    ultimo_video: ultimo ? new Date(ultimo).toISOString() : null };
});
const todos = canais.flatMap(c => c.ultimos.map(v => ({ ...v, canal: c.nome })));
const retrato = {
  quando: new Date().toISOString(), anterior: ant.quando || null,
  totais: { canais: canais.length, inscritos: canais.reduce((s, c) => s + (c.inscritos || 0), 0),
    d_inscritos: canais.reduce((s, c) => s + (c.d_inscritos || 0), 0), views_recentes: canais.reduce((s, c) => s + c.views_recentes, 0),
    novos_7d: canais.reduce((s, c) => s + c.novos_7d, 0) },
  destaques: todos.filter(v => v.ganho != null).sort((a, b) => b.ganho - a.ganho).slice(0, 8),
  mais_vistos: todos.slice().sort((a, b) => b.views - a.views).slice(0, 8),
  alertas: [
    ...canais.filter(c => c.status === 'ativo' && c.parado).map(c => '⏸️ ' + c.nome + ': sem vídeo novo há mais de 3 dias'),
    ...canais.flatMap(c => c.zerados.slice(0, 3).map(v => '🧊 ' + c.nome + ': "' + v.titulo.slice(0, 60) + '" com ' + v.views + ' views depois de 48 h')),
    ...canais.filter(c => !c.ok).map(c => '⚠️ ' + c.nome + ': não deu para ler (' + c.erro + ')') ],
  canais };
return [{ json: { retrato: JSON.stringify(retrato), dia: retrato.quando.slice(0, 10), resumo: retrato.totais, alertas: retrato.alertas.length } }];

// Painel do radar: lê o último retrato e desenha a página.
// ── Moldura das páginas (mesmo visual em todos os fluxos grátis) ──
function pagina(titulo, corpo, script) {
  const css = `
:root{--fundo:#f6f5f2;--cartao:#fff;--texto:#1d1d1b;--suave:#6b6b66;--linha:#e3e1db;--acento:#0f766e;--acento2:#115e59;--erro:#b42318;--ok:#067647}
@media (prefers-color-scheme:dark){:root{--fundo:#121412;--cartao:#1b1e1c;--texto:#ecebe7;--suave:#a3a39d;--linha:#2c302d;--acento:#2dd4bf;--acento2:#5eead4;--erro:#f97066;--ok:#47cd89}}
*{box-sizing:border-box}body{margin:0;background:var(--fundo);color:var(--texto);font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
main{max-width:760px;margin:0 auto;padding:20px 16px 48px}h1{font-size:1.45rem;margin:.2em 0 .1em}h2{font-size:1.1rem;margin:1.2em 0 .5em}
.sub{color:var(--suave);margin:0 0 18px}.cartao{background:var(--cartao);border:1px solid var(--linha);border-radius:14px;padding:16px;margin:12px 0}
label{display:block;font-weight:600;margin:12px 0 6px}textarea,input,select{width:100%;padding:11px 12px;border:1px solid var(--linha);border-radius:10px;background:var(--fundo);color:var(--texto);font:inherit}
textarea{min-height:120px;resize:vertical}.linha{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}
button,.botao{display:inline-block;background:var(--acento);color:#fff;border:0;border-radius:10px;padding:12px 18px;font:600 1rem system-ui,sans-serif;cursor:pointer;text-decoration:none;margin-top:14px}
@media (prefers-color-scheme:dark){button,.botao{color:#04211e}}
button[disabled]{opacity:.55;cursor:wait}.botao.sec{background:transparent;color:var(--acento);border:1px solid var(--acento)}
.aviso{color:var(--suave);font-size:.9rem}.erro{color:var(--erro);font-weight:600}.ok{color:var(--ok);font-weight:600}
.grade{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.grade img,.grade video{width:100%;border-radius:10px;border:1px solid var(--linha);background:#000}
video,audio{width:100%;margin-top:10px;border-radius:10px}pre{white-space:pre-wrap;background:var(--fundo);border:1px solid var(--linha);border-radius:10px;padding:12px;font-size:.9rem}
.barra{height:8px;background:var(--linha);border-radius:99px;overflow:hidden;margin:10px 0}.barra i{display:block;height:100%;background:var(--acento);width:0;transition:width .6s}
.selo{display:inline-block;font-size:.78rem;border:1px solid var(--linha);border-radius:99px;padding:2px 9px;color:var(--suave);margin:2px 4px 2px 0}
footer{color:var(--suave);font-size:.82rem;margin-top:28px}`;
  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<meta name="robots" content="noindex"><title>' + titulo + '</title><style>' + css + '</style></head><body><main>' + corpo +
    '<footer>Feito com serviços grátis e sem chave (Hugging Face, Pollinations, Bing/Google Tradutor). Pode demorar ou falhar quando eles estão cheios.</footer>' +
    '</main>' + (script ? '<script>' + script + '</script>' : '') + '</body></html>';
}
const escHtml = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

let r = null;
try { r = JSON.parse($input.first().json.retrato || 'null'); } catch (e) { r = null; }
const n = x => x == null ? '–' : Number(x).toLocaleString('pt-BR');
const d = x => x == null ? '' : (x > 0 ? ' <span class="ok">+' + n(x) + '</span>' : x < 0 ? ' <span class="erro">' + n(x) + '</span>' : ' <span class="aviso">=</span>');
const dataBR = s => s ? new Date(s).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) : '–';
let corpo = '<h1>📊 Radar dos canais</h1>';
if (!r) {
  corpo += '<p class="sub">Ainda não há leitura. Aperte o botão (leva 1 a 2 minutos) e recarregue.</p>';
} else {
  const t = r.totais;
  corpo += '<p class="sub">Leitura de ' + dataBR(r.quando) + (r.anterior ? ' · comparado com ' + dataBR(r.anterior) : '') +
    '. Dados públicos do YouTube (sem login, sem chave).</p>' +
    '<div class="linha">' +
    '<div class="cartao"><div class="aviso">Inscritos (todos)</div><h2>' + n(t.inscritos) + d(t.d_inscritos) + '</h2></div>' +
    '<div class="cartao"><div class="aviso">Views dos 15 últimos de cada</div><h2>' + n(t.views_recentes) + '</h2></div>' +
    '<div class="cartao"><div class="aviso">Vídeos novos em 7 dias</div><h2>' + n(t.novos_7d) + '</h2></div></div>';
  if (r.alertas.length) corpo += '<div class="cartao"><h2>Alertas</h2>' + r.alertas.map(a => '<div>' + escHtml(a) + '</div>').join('') + '</div>';
  if (r.destaques.length) corpo += '<div class="cartao"><h2>Quem mais ganhou views desde a última leitura</h2>' +
    r.destaques.map(v => '<div>+' + n(v.ganho) + ' · <a href="https://youtu.be/' + v.id + '" target="_blank">' + escHtml(v.titulo) + '</a> <span class="selo">' + escHtml(v.canal) + '</span></div>').join('') + '</div>';
  corpo += '<div class="cartao" style="overflow-x:auto"><h2>Canais</h2><table style="width:100%;border-collapse:collapse;font-size:.92rem">' +
    '<tr style="text-align:left"><th>Canal</th><th>Inscritos</th><th>Vídeos</th><th>Views (15 últ.)</th><th>Novos 7d</th><th>Último vídeo</th></tr>' +
    r.canais.slice().sort((a, b) => (b.d_inscritos || 0) - (a.d_inscritos || 0) || (b.views_recentes - a.views_recentes)).map(c =>
      '<tr style="border-top:1px solid var(--linha)"><td><a href="https://www.youtube.com/channel/' + c.yt_id + '" target="_blank">' + escHtml(c.nome) +
      '</a> <span class="selo">' + escHtml(c.status || '') + '</span></td><td>' + n(c.inscritos) + d(c.d_inscritos) + '</td><td>' + n(c.videos) + d(c.d_videos) +
      '</td><td>' + n(c.views_recentes) + '</td><td>' + c.novos_7d + '</td><td>' + (c.ultimo_video ? dataBR(c.ultimo_video).slice(0, 10) : '–') + '</td></tr>').join('') +
    '</table></div>';
  corpo += '<div class="cartao"><h2>Mais vistos entre os recentes</h2>' + r.mais_vistos.map(v => '<div>' + n(v.views) +
    ' · <a href="https://youtu.be/' + v.id + '" target="_blank">' + escHtml(v.titulo) + '</a> <span class="selo">' + escHtml(v.canal) + '</span></div>').join('') + '</div>';
}
corpo += '<button id="ir">Atualizar agora</button><p id="estado" class="aviso">Atualiza sozinho todo dia às 7h20.</p>';
const script = `document.getElementById('ir').onclick = async () => {
  const b = document.getElementById('ir'); b.disabled = true;
  document.getElementById('estado').textContent = 'Lendo os canais... (1 a 2 minutos; depois recarregue a página)';
  try { await fetch('gratis-radar-atualizar', { method: 'POST' }); } catch (e) {}
  setTimeout(() => location.reload(), 90000);
};`;
return [{ json: { html: pagina('Radar dos canais', corpo, script) } }];
